//! 🎟️ Prepaid domain frames preserve real Original body, callback and qualification owners.
use super::*;
use crate::{OriginalWorkFailure,OriginalJobFixtureCaller,OriginalDomainProjection,OperationId,Generation,close_original_effect_step};
use crate::original_failure_test_support::{BodyFailure,projected,wire_value,wire_progress,independent_body};
use semio_framework_diagnostic::FaultMessageOwner;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress as P,RetainedWorkPoll};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_value_testing_allocator::{observe_retirement_allocations,refuse_one_allocation_on_this_thread};
use serde_json::{Value,json};
type Failure=OriginalWorkFailure<BodyFailure>;
fn clock()->Option<u64>{Some(0)}
fn native_value(message:&str)->Value{json!({"primary":{"kind":"value","original":wire_value("invariantViolated",message,P::default())},"effects":wire_progress(P::default())})}
fn close_frame(frame:&mut OriginalDomainReservation<Failure>,caller:&mut OriginalJobFixtureCaller,stock:RetainedCloneGrant,bound:usize){
 if !frame.terminal_is_empty(){caller.turn(stock,|cx|{for axis in ["items","depth"]{let mut denied=cx.retained_grant();if axis=="items"{denied.maximum_items=0}else{denied.maximum_depth=0}let before=cx.retained_progress();let fuel=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(ran,heap)=observe(||cx.with_original_effect(denied,|_,effect|frame.close_step(body,effect)));if let Some((poll,performed))=ran?{let RetainedWorkPoll::Complete(turn)=poll else{panic!("denied original close stayed pending")};assert_eq!((turn.work,performed),(0,0));match turn.result{Ok(step)=>assert_eq!(step.progress(),P::default()),Err(error)=>assert_eq!(error.retained_progress(),P::default())}}assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(!frame.is_closing());}let d=frame.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;assert_eq!(d,semio_framework_value::RetirementDemand{depth:1,..Default::default()});let fuel=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,d,|effect|frame.close_step(body,effect)));let p=result?.progress();assert_eq!(p,P{copied_items:1,..Default::default()});assert_eq!(fuel-cx.fuel_remaining(),1);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(frame.is_closing());Ok(())}).unwrap();}
 for _ in 0..bound{if frame.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|same|{let d=frame.retirement_demands(same.retained_grant().maximum_copy_bytes)?;let fuel=same.fuel_remaining();let body=same.retained_grant().maximum_copy_bytes;let mut work=0;let(result,heap)=observe(||close_original_effect_step(same,d,|effect|{let poll=frame.close_step(body,effect);work=poll.work();poll}));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(u128::from(fuel-same.fuel_remaining()),work);Ok(())})).unwrap();}
 assert!(frame.terminal_is_empty());
}
#[test]
fn real_prepaid_domain_frames_keep_actual_allocation_body_credit_causes_and_paid_close(){
 let control:Value=serde_json::from_str(include_str!("../../../🎟️context/case.json")).unwrap();let contract:Value=serde_json::from_str(include_str!("../../../🎟️context/case.schema.json")).unwrap();for(k,v)in control.as_object().unwrap(){assert_eq!(&contract["properties"][k]["const"],v);}
 let law:Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(law["stock"].clone()).unwrap();let bound=law["maximumObservedTurns"].as_u64().unwrap()as usize;
 for(ordinal,row)in law["cases"].as_array().unwrap().iter().enumerate(){
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,clock,law["deadlineUs"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());
  let mut foreign=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,clock,law["deadlineUs"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());
  let mut frame=OriginalDomainReservation::<Failure>::new();let input=row["message"].as_str().unwrap();let input_pointer=input.as_ptr();let mut occupied=None;let mut body_progress=P::default();let mut body_pointer=None;let mut projection_pointer=0;
  caller.turn(stock,|cx|{
   let d=original_domain_failure_demand::<Failure>();for axis in law["deniedPreparationAxes"].as_array().unwrap(){let mut denied=cx.retained_grant();match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"capacity"=>denied.maximum_capacity_bytes=d.capacity_bytes-1,"depth"=>denied.maximum_depth=d.depth-1,_=>panic!("unknown preparation axis")}let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observe(||cx.with_retained_loan(denied,|same|frame.prepare(same)));assert!(!result?);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(!frame.ready());}
   let before=cx.retained_progress();let fuel=cx.fuel_remaining();let((result,refused),heap)=observe_retirement_allocations(||refuse_one_allocation_on_this_thread(||frame.prepare(cx)));let failure=result.unwrap_err();assert_eq!(refused,1);assert_eq!(heap,(0,0));assert_eq!(cx.fuel_remaining()+1,fuel);assert_eq!(cx.retained_progress(),before);assert!(!frame.ready());assert!(matches!(&failure.primary,crate::OriginalTurnPrimary::Value(error)if error.kind==semio_framework_value::ValueRefusalKind::AllocationFailed&&error.message=="original domain frame allocation refused"));assert_eq!(failure.effects,P::default());assert_eq!(input.as_ptr(),input_pointer);
   let mut called=false;let fuel=cx.fuel_remaining();assert!(frame.with_body(cx,|_,_|{called=true;Ok(())})?.is_none());assert!(!called);assert_eq!(cx.fuel_remaining(),fuel);
   let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observe_retirement_allocations(||frame.prepare(cx));assert!(result?);assert_eq!(heap,(d.capacity_bytes,0));assert_eq!(cx.retained_progress().retained_capacity_bytes-before.retained_capacity_bytes,d.capacity_bytes);assert_eq!(cx.retained_progress().copied_items-before.copied_items,1);assert_eq!(fuel-cx.fuel_remaining(),1);assert!(frame.ready());assert!(!frame.pending());
   let source=frame.allocation_identity().unwrap();let fuel=cx.fuel_remaining();let before=cx.retained_progress();assert!(frame.prepare(cx)?);assert_eq!(cx.fuel_remaining(),fuel);assert_eq!(cx.retained_progress(),before);assert_eq!(frame.allocation_identity().unwrap(),source);Ok(())
  }).unwrap();
  caller.turn(stock,|cx|{
   for axis in law["deniedBodyAxes"].as_array().unwrap(){let mut denied=cx.retained_grant();match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"depth"=>denied.maximum_depth=0,_=>panic!("unknown body axis")}let before=cx.retained_progress();let fuel=cx.fuel_remaining();let mut called=false;let(result,heap)=observe(||cx.with_retained_loan(denied,|same|frame.with_body(same,|_,_|{called=true;Ok(())})));assert!(result?.is_none());assert!(!called);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(frame.ready());assert!(!frame.pending());}Ok(())
  }).unwrap();
  caller.turn(stock,|cx|{
   let mut phase=cx.retained_grant();phase.maximum_items=law["reserve"]["items"].as_u64().unwrap()as usize;cx.bind_original_retained_total(phase)?;let before=cx.retained_progress();let fuel=cx.fuel_remaining();let mut called=false;let(result,heap)=observe(||frame.with_body(cx,|_,_|{called=true;Ok(())}));assert!(result?.is_none());assert!(!called);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);Ok(())
  }).unwrap();
  if row["callbackRefusal"].as_bool().unwrap(){caller.turn(stock,|cx|{let turn=FaultMessageOwner::construct(input,cx.retained_grant());cx.consume_fuel(u64::try_from(turn.work).unwrap());let(mut owner,p)=turn.result?;cx.consume_retained(p)?;let turn=owner.take_step(&mut occupied,cx.retained_grant());cx.consume_fuel(u64::try_from(turn.work).unwrap());let p=turn.result?.progress();cx.consume_retained(p)?;let(_,heap)=observe(||drop(owner));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();}
  let quantum=RetainedCloneGrant{maximum_items:law["quantum"].as_u64().unwrap()as usize,..stock};caller.turn(quantum,|cx|{
   let current=cx.retained_grant();let lifetime=cx.original_total_retained_grant();let fuel=cx.fuel_remaining();let total_fuel=cx.original_total_fuel_remaining();let before=cx.retained_progress();
   let(result,heap)=observe(||frame.with_body(cx,|same,slot|{
    assert_eq!(same.retained_grant().maximum_items,law["quantum"].as_u64().unwrap()as usize);assert!(same.retained_grant().maximum_items+law["reserve"]["items"].as_u64().unwrap()as usize<=lifetime.maximum_items);assert_eq!(same.fuel_remaining()+law["reserve"]["fuel"].as_u64().unwrap(),total_fuel);assert_eq!(current.maximum_items,1);
    let birth=FaultMessageOwner::construct(input,same.retained_grant());let birth_work=birth.work;let(mut owner,p)=birth.result?;assert!(owner.ready());body_pointer=Some((owner.fault().unwrap().message.as_ptr()as usize,owner.fault().unwrap().scope.as_ref()as*const _ as usize));body_progress=p;
    let mut take_work=0;let callback=if row["callbackRefusal"].as_bool().unwrap(){let turn=owner.take_step(&mut occupied,same.retained_grant());take_work=turn.work;Some(turn.result.unwrap_err())}else{None};let cpu=u64::try_from(birth_work+take_work).unwrap();let failure=OriginalWorkFailure::fold(same,Some(BodyFailure{ordinal:ordinal as u64,owner,progress:p}),p,cpu).unwrap_err();*slot=Some(failure);
    if let Some(error)=callback{Err(error.into())}else{Ok(())}
   }));let actual=result?;assert_eq!(actual.is_none(),row["callbackRefusal"].as_bool().unwrap());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(body_progress.retained_capacity_bytes,body_progress.released_bytes));assert_eq!(cx.retained_progress().retained_capacity_bytes-before.retained_capacity_bytes,body_progress.retained_capacity_bytes);assert_eq!(fuel-cx.fuel_remaining(),1+u64::from(row["callbackRefusal"].as_bool().unwrap()));assert!(frame.pending());
   let mut called=false;let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observe(||frame.with_body(cx,|_,_|{called=true;Ok(())}));assert!(result?.is_none());assert!(!called);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())
  }).unwrap();
  if row["foreignPublication"].as_bool().unwrap(){foreign.turn(stock,|cx|{
   for axis in ["items","depth"]{let mut denied=cx.retained_grant();if axis=="items"{denied.maximum_items=0}else{denied.maximum_depth=0}let fuel=cx.fuel_remaining();let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(denied,|same|Ok(admit_original_domain_failure(&mut frame,same)?.is_none())));assert!(result?);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);}
   let refused=&law["foreignPublicationRefusal"];for _ in 0..refused["repeats"].as_u64().unwrap(){let fuel=cx.fuel_remaining();let before=cx.retained_progress();let(result,heap)=observe(||admit_original_domain_failure(&mut frame,cx));let refusal=result.expect_err("a foreign Source cannot publish another Source's prepaid frame");assert!(matches!(&refusal.primary,crate::OriginalTurnPrimary::Value(error)if serde_json::to_value(error.kind).unwrap()==refused["kind"]&&error.message==refused["message"].as_str().unwrap()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress().copied_items,before.copied_items+refused["copiedItems"].as_u64().unwrap()as usize);assert_eq!(fuel-cx.fuel_remaining(),refused["cpu"].as_u64().unwrap());assert!(frame.pending());}Ok(())
  }).unwrap();}
  let original=json!({"primary":independent_body(ordinal as u64,input),"effects":wire_progress(body_progress)});let expected=if row["callbackRefusal"].as_bool().unwrap(){let mut root=serde_json::Map::new();root.insert("original".into(),original);root.insert("callbackRefusal".into(),native_value("Fault publication requires an empty receiver"));Value::Object(root)}else{original};
  caller.turn(stock,|cx|{
   let payload=frame.pending_projection().unwrap();projection_pointer=payload.projection_identity();assert_eq!(projected(payload,&mut Vec::new()),expected);
   let pointer=frame.pending_original().unwrap().primary().unwrap().owner.fault().unwrap().message.as_ptr()as usize;let scope=frame.pending_original().unwrap().primary().unwrap().owner.fault().unwrap().scope.as_ref()as*const _ as usize;assert_eq!((pointer,scope),body_pointer.unwrap());
   for axis in law["deniedPublicationAxes"].as_array().unwrap(){let mut denied=cx.retained_grant();match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"depth"=>denied.maximum_depth=0,_=>panic!("unknown publication axis")}let fuel=cx.fuel_remaining();let before=cx.retained_progress();let mut output=None;let(result,heap)=observe(||cx.with_retained_loan(denied,|same|{output=admit_original_domain_failure(&mut frame,same)?;Ok(())}));result?;assert!(output.is_none());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert!(frame.pending());}
   if row["cancel"].as_bool().unwrap(){let p=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant()).expect("funded original cancel flag transition");cx.consume_retained(p)?;cx.consume_fuel(1);let before=cx.retained_progress();let fuel=cx.fuel_remaining();let mut called=false;assert!(!frame.prepare(cx)?);assert!(frame.with_body(cx,|_,_|{called=true;Ok(())})?.is_none());assert!(!called);assert!(admit_original_domain_failure(&mut frame,cx)?.is_none());assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);return Ok(())}
   let before=cx.retained_progress();let fuel=cx.fuel_remaining();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut output=None;let(result,heap)=observe(||cx.with_retained_loan(grant,|same|{output=admit_original_domain_failure(&mut frame,same)?;Ok(())}));result?;let failure=output.expect("paid reserved header transfers");assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(fuel-cx.fuel_remaining(),1);assert_eq!(cx.retained_progress().copied_items-before.copied_items,1);assert_eq!(cx.retained_progress().copied_bytes,before.copied_bytes);assert_eq!(cx.retained_progress().retained_capacity_bytes,before.retained_capacity_bytes);assert_eq!(cx.retained_progress().released_bytes,before.released_bytes);assert!(frame.terminal_is_empty());let projection=failure.primary_domain().unwrap().projection();assert_eq!(projection.projection_identity(),projection_pointer);assert_eq!(projected(projection,&mut Vec::new()),expected);assert_eq!(failure.effects,P::default());crate::original_failure_test_support::close(failure,cx,bound);Ok(())
  }).unwrap();
  close_frame(&mut frame,&mut caller,stock,bound);let(_,heap)=observe(||drop(frame));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if occupied.is_some(){caller.turn(stock,|cx|{crate::original_failure_test_support::close(occupied.take(),cx,bound);Ok(())}).unwrap();}foreign.retire(stock);caller.retire(stock);
 }
}


#[test]
fn actual_parent_controlled_retirement_retains_and_closes_prepaid_domain_frame_and_original_body(){
 let law:Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert!(law["parentOwnedClose"].as_bool().unwrap());let stock:RetainedCloneGrant=serde_json::from_value(law["stock"].clone()).unwrap();let bound=law["maximumObservedTurns"].as_u64().unwrap()as usize;let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()+1),Generation(law["generation"].as_u64().unwrap()),stock,clock,law["deadlineUs"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());
 caller.turn(stock,|cx|{let mut reservation=OriginalDomainReservation::<Failure>::new();assert!(reservation.prepare(cx)?);assert!(reservation.with_body(cx,|same,slot|{let turn=FaultMessageOwner::construct(law["cases"][0]["message"].as_str().unwrap(),same.retained_grant());let work=u64::try_from(turn.work).unwrap();let(owner,p)=turn.result?;let failure=OriginalWorkFailure::fold(same,Some(BodyFailure{ordinal:0,owner,progress:p}),p,work).unwrap_err();*slot=Some(failure);Ok(())})?.is_some());assert!(reservation.pending());crate::original_failure_test_support::close(reservation,cx,bound);Ok(())}).unwrap();caller.retire(stock);
}
